//go:build integration

package conn

import (
	"context"
	"errors"
	"net"
	"sync"
	"testing"
	"time"

	"github.com/WuKongIM/WuKongIM/pkg/transport/internal/core"
)

func newInboundTestConn(t *testing.T) *Conn {
	t.Helper()
	raw, peer := net.Pipe()
	c := New(raw, Config{}, nil)
	t.Cleanup(func() { c.Close(nil); _ = peer.Close() })
	return c
}

func TestInboundTrackingCancellationOwnership(t *testing.T) {
	for _, budget := range []time.Duration{0, time.Hour} {
		t.Run(budget.String(), func(t *testing.T) {
			c := newInboundTestConn(t)
			other := newInboundTestConn(t)
			first, finish, err := c.TrackInbound(1, budget)
			if err != nil {
				t.Fatal(err)
			}
			second, finishSecond, err := c.TrackInbound(2, budget)
			if err != nil {
				t.Fatal(err)
			}
			defer finishSecond()
			foreign, finishForeign, err := other.TrackInbound(1, budget)
			if err != nil {
				t.Fatal(err)
			}
			defer finishForeign()
			if _, _, err := c.TrackInbound(1, budget); !errors.Is(err, core.ErrInvalidFrame) {
				t.Fatalf("duplicate: %v", err)
			}
			if first.Err() != nil {
				t.Fatal("duplicate canceled original")
			}
			c.CancelInbound(99)
			c.CancelInbound(1)
			if first.Err() != context.Canceled || second.Err() != nil || foreign.Err() != nil {
				t.Fatal("cancel escaped exact request ownership")
			}
			finish()
			replacement, finishReplacement, err := c.TrackInbound(1, budget)
			if err != nil {
				t.Fatal(err)
			}
			// Finish is a terminal-owner operation, called once before ID reuse.
			defer finishReplacement()
			c.Close(nil)
			if replacement.Err() != context.Canceled || second.Err() != context.Canceled || foreign.Err() != nil {
				t.Fatal("close escaped connection ownership or missed a request")
			}
			if _, _, err := c.TrackInbound(3, budget); !errors.Is(err, core.ErrStopped) {
				t.Fatalf("post-close admission: %v", err)
			}
		})
	}
}

func TestInboundTrackingBudgetExpiry(t *testing.T) {
	c := newInboundTestConn(t)
	ctx, finish, err := c.TrackInbound(1, 5*time.Millisecond)
	if err != nil {
		t.Fatal(err)
	}
	defer finish()
	if _, ok := ctx.Deadline(); !ok {
		t.Fatal("missing deadline")
	}
	select {
	case <-ctx.Done():
		if ctx.Err() != context.DeadlineExceeded {
			t.Fatalf("expiry: %v", ctx.Err())
		}
	case <-time.After(time.Second):
		t.Fatal("budget did not expire")
	}
}

func TestInboundTrackingCloseRacesAdmission(t *testing.T) {
	for round := 0; round < 20; round++ {
		c := newInboundTestConn(t)
		start := make(chan struct{})
		var wg sync.WaitGroup
		for i := 0; i < 16; i++ {
			wg.Add(1)
			go func(id uint64) {
				defer wg.Done()
				<-start
				ctx, finish, err := c.TrackInbound(id, time.Hour)
				if err != nil {
					if !errors.Is(err, core.ErrStopped) {
						t.Errorf("admission: %v", err)
					}
					return
				}
				defer finish()
				select {
				case <-ctx.Done():
					if ctx.Err() != context.Canceled {
						t.Errorf("close: %v", ctx.Err())
					}
				case <-time.After(time.Second):
					t.Error("close missed admitted request")
				}
			}(uint64(i))
		}
		close(start)
		c.Close(nil)
		wg.Wait()
	}
}

